use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// The hosts this node's `HTTPClient` handle is scoped to. A request outside
/// this set would trap at the boundary and take the whole tick down with it,
/// so such URLs are refused here, as data, without ever being asked for.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extract the host of an http(s) URL, strictly. Anything ambiguous
/// (userinfo, explicit port, odd characters) is rejected rather than guessed
/// at, so this parse cannot disagree with the host's in a permissive direction.
fn host_of(url: &str) -> Result<String, &'static str> {
    if url.is_empty() {
        return Err("empty url");
    }
    if url
        .chars()
        .any(|c| !c.is_ascii() || c.is_ascii_control() || c == ' ' || c == '\\')
    {
        return Err("url contains disallowed characters");
    }
    let (scheme, rest) = url.split_once("://").ok_or("url has no scheme")?;
    let scheme = scheme.to_ascii_lowercase();
    if scheme != "https" && scheme != "http" {
        return Err("unsupported url scheme");
    }
    let end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..end];
    if authority.is_empty() {
        return Err("url has no host");
    }
    if authority.contains('@') {
        return Err("url userinfo is not permitted");
    }
    if authority.contains(':') || authority.contains('[') || authority.contains(']') {
        return Err("explicit port or ip literal is not permitted");
    }
    if !authority
        .chars()
        .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '.')
    {
        return Err("url host contains disallowed characters");
    }
    Ok(authority.to_ascii_lowercase())
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for raw in subscriptions.urls {
            let url = raw.trim().to_string();

            let host = match host_of(&url) {
                Ok(h) => h,
                Err(e) => {
                    failures.push(FetchFailure {
                        url,
                        error: e.to_string(),
                    });
                    continue;
                }
            };

            if !ALLOWED_HOSTS.iter().any(|a| *a == host) {
                failures.push(FetchFailure {
                    url,
                    error: "host is outside this node's allowlist; not fetched".to_string(),
                });
                continue;
            }

            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
